import {crearRevisionGoogleUI} from './revision-google.mjs';
import {$,estado,nodo,aviso,api,fallo,boton,enlace,opciones,mutar,sesion,instalarLogin,tabla} from './comun-centro.mjs';
import {filtrarMonitor} from './monitor-filtros.mjs';
import {formatearCantidad,formatearCompacto} from './cantidades.mjs';
const seleccionZIP=new Set();
let ctx,datos,ancla,modo='gantt',vista='dashboard',editar=null,panelLimite=30,seqDashboard=0;
const hoy=()=>ctx?.hoy||new Intl.DateTimeFormat('en-CA',{timeZone:'America/Guayaquil'}).format(new Date());
const sumar=(f,n)=>new Date(Date.parse(f+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);
const lunes=f=>sumar(f,-((new Date(f+'T12:00Z').getUTCDay()+6)%7));
const fmt=f=>f?new Date(f+'T12:00Z').toLocaleDateString('es-EC',{timeZone:'UTC',day:'numeric',month:'short'}):'—';
function filtrados(){return datos.eventos.filter(e=>!$('sede').value||e.sede===$('sede').value);}
function mostrarVista(v){
 const permiso={usuarios:'usuarios',analitica:'analitica',reportes:'exportar'}[v];if(permiso&&ctx&&!ctx.perfil.permisos[permiso])v='dashboard';
 vista=v;for(const el of document.querySelectorAll('[id^=vista-]'))el.hidden=el.id!=='vista-'+v;for(const b of document.querySelectorAll('[data-vista]'))b.classList.toggle('activo',b.dataset.vista===v);
 if(v==='reportes')void cargarReporteCliente();if(v==='usuarios')void usuarios().catch(fallo);if(v==='analitica')void analitica().catch(fallo);window.location.hash=v;document.dispatchEvent(new CustomEvent('ims:vista',{detail:{titulo:({dashboard:'Centro de Mando',perfil:'Mi perfil',usuarios:'Usuarios y permisos',analitica:'Analítica del equipo',reportes:'Reportes por cliente'})[v]}}));
}
function tarjetas(){
 const ks=datos.indicadores,lista=[['Vencidos',ks.vencidos,'cronograma','rojo'],['Hoy',ks.hoy,'programados','amarillo'],['Próx. 7 días',ks.proximos,'en agenda','azul'],['Entregados año',ks.entregados,'en panel','verde'],['Clientes activos',ks.clientesActivos,'mes en curso','azul'],['Unidades',formatearCompacto(ks.unidades),'año',''],['Referencias',formatearCompacto(ks.referencias),'año',''],['Posiciones',formatearCompacto(ks.posiciones),'año',''],['Avance mes',Math.round(ks.avanceMes)+'%','entregados / total','verde'],['Cumplimiento año',Math.round(ks.cumplimientoAnio)+'%','programado / ejecutado','azul']];
 $('kpis').replaceChildren(...lista.map(([t,v,s,cl])=>{const e=nodo('div',undefined,'tarjeta');e.title=t==='Unidades'?formatearCantidad(ks.unidades)+' unidades':t==='Referencias'?String(ks.referencias):t==='Posiciones'?String(ks.posiciones):String(v);e.append(nodo('small',t),nodo('div',v,'cifra '+cl),nodo('small',s));return e;}));
 $('publicados').textContent=datos.publicados+' inventarios con resultado publicado.';
}
function eventosAgenda(){const q=$('agenda-buscar').value.trim().toLocaleLowerCase('es'),estado=$('agenda-estado').value;return filtrados().filter(e=>(!estado||e.estado===estado)&&(!q||(e.cliente+' '+e.titulo+' '+e.responsable_nombre).toLocaleLowerCase('es').includes(q)));}
function calendario(){
 if(['anio','gantt'].includes(modo)){matrizAnual();return;}
 const desde=modo==='semana'?lunes(ancla):ancla.slice(0,7)+'-01',hasta=modo==='semana'?sumar(desde,6):sumar((new Date(Date.parse(desde+'T12:00Z')).getUTCMonth()===11?String(Number(desde.slice(0,4))+1)+'-01-01':desde.slice(0,5)+String(Number(desde.slice(5,7))+1).padStart(2,'0')+'-01'),-1);
 $('periodo').textContent=fmt(desde)+' – '+fmt(hasta)+' '+desde.slice(0,4);const es=eventosAgenda().filter(e=>e.fecha_inicio<=hasta&&(e.fecha_final_calendario||fin(e))>=desde);const out=$('calendario');out.replaceChildren();
 if(modo==='semana'){
  const cab=nodo('div',undefined,'semana');cab.append(nodo('div','Cliente / tarea'));for(let i=0;i<7;i++)cab.append(nodo('div',fmt(sumar(desde,i)),'dia'));out.append(cab);
  for(const e of es){const r=nodo('div',undefined,'semana'),label=nodo('div');label.append(boton(e.cliente,()=>detalleEvento(e)),nodo('small',e.titulo));r.append(label);for(let i=0;i<7;i++){const f=sumar(desde,i),cl=[e.fecha_inicio<=f&&fin(e)>=f?(e.estado==='Entregado'?'entregado':e.estado==='Pausado'?'pausado':'rango'):'',f===hoy()?'hoy':''].join(' ');const cel=nodo('div','',cl);if(e.fecha_inicio<=f&&fin(e)>=f){const b=boton('●',()=>detalleEvento(e),'agenda-celda');b.setAttribute('aria-label',e.cliente+' · '+e.titulo+' · '+f);cel.append(b);}r.append(cel);}out.append(r);}
 }else{
  const grid=nodo('div',undefined,'mes'),inicio=lunes(desde);for(let i=0;i<42;i++){const f=sumar(inicio,i),cel=nodo('div');cel.append(nodo('strong',fmt(f)));for(const e of es.filter(e=>e.fecha_inicio<=f&&fin(e)>=f))cel.append(boton(e.cliente,()=>detalleEvento(e),'evento-mini'));grid.append(cel);}out.append(grid);
 }
 if(!es.length)out.append(nodo('p','No hay eventos en este periodo.'));
}
function fin(e){const f=sumar(e.fecha_inicio,Math.max(1,Number(e.duracion)||1)-1);return e.fecha_fin&&e.fecha_fin>f?e.fecha_fin:f;}
function cronograma(){
 const filtro=$('filtro').value,rango=$('rango').value,q=$('buscar').value.toLocaleLowerCase('es'),desde=lunes(ancla),mes=ancla.slice(0,7);
 const lista=filtrados().filter(e=>(!q||(e.cliente+' '+e.titulo+' '+e.responsable_nombre).toLocaleLowerCase('es').includes(q))&&(rango==='todos'||rango==='mes'&&e.fecha_inicio.slice(0,7)===mes||rango==='semana'&&e.fecha_inicio<=sumar(desde,6)&&fin(e)>=desde)&&(filtro==='todos'||filtro==='entregados'&&e.estado==='Entregado'||filtro==='pendientes'&&e.estado!=='Entregado'||filtro==='urgentes'&&e.estado!=='Entregado'&&(e.fecha_inicio<hoy()||['Alta','Urgente'].includes(e.prioridad))||filtro==='proximos'&&e.fecha_inicio>=hoy()&&e.fecha_inicio<=sumar(hoy(),7)||filtro==='sin-archivo'&&!e.archivo_drive&&!e.inventarios.length||filtro==='mios'&&(e.responsable_id===estado.sesion.usuario.actorId||e.equipo.some(q=>q.actor_id===estado.sesion.usuario.actorId&&q.estado==='ACTIVO'))));
 tabla($('cronograma'),['Fecha','Cliente / tarea','Responsable','Estado','Acciones'],lista.map(e=>{const desc=nodo('div');desc.append(nodo('strong',e.cliente),nodo('div',e.titulo),nodo('small',e.sede+' · '+e.categoria));const a=nodo('div',undefined,'acciones');a.append(boton('Ver',()=>detalleEvento(e)));const propio=e.responsable_id===estado.sesion.usuario.actorId||ctx.perfil.rol==='ADMIN'||!e.responsable_id&&ctx.perfil.permisos.crear;if(e.estado!=='Entregado'&&propio){a.append(boton(e.estado==='En curso'?'Pausar':'Iniciar',()=>accion(e,e.estado==='En curso'?'pausar':'iniciar')),boton('Fin',()=>finalizar(e)));}return [fmt(e.fecha_inicio),desc,e.responsable_nombre||'Sin responsable',nodo('span',e.estado,'estado-pill'),a];}));
}
function archivos(){const q=$('buscar-panel').value.toLocaleLowerCase('es'),ps=datos.panel.filter(p=>(!$('sede').value||p.sede===$('sede').value)&&(!q||(p.cliente+' '+p.archivo_drive).toLocaleLowerCase('es').includes(q))).slice(0,panelLimite);tabla($('panel-archivos'),['Cliente','Sede','Inicio / entrega','Estado','Unidades','Archivo'],ps.map(p=>{const a=nodo('div');if(p.inventarios)for(const i of p.inventarios){const l=nodo('label',undefined,'check'),cb=nodo('input');cb.type='checkbox';cb.checked=seleccionZIP.has(i.id);cb.onchange=()=>cb.checked?seleccionZIP.add(i.id):seleccionZIP.delete(i.id);l.append(cb,enlace(i.codigo,(i.nativo?'/ims':'/inventarios')+'?inventario='+i.id));a.append(l);}if(p.archivo_drive)a.append(enlace('Referencia original','https://docs.google.com/spreadsheets/d/'+encodeURIComponent(p.archivo_drive)));return[p.cliente,p.sede,fmt(p.fecha_inicio)+' / '+fmt(p.fecha_fin),p.estado,p.unidades===null?'—':formatearCantidad(p.unidades),a];}));}
function tendencia(){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 720 170');svg.setAttribute('role','img');svg.setAttribute('aria-label','Inventarios entregados por mes');const max=Math.max(1,...datos.indicadores.tendencia.map(x=>x.entregados));for(const [i,r] of datos.indicadores.tendencia.entries()){const b=document.createElementNS(ns,'rect');b.setAttribute('x',String(i*59+12));b.setAttribute('y',String(140-r.entregados*110/max));b.setAttribute('width','35');b.setAttribute('height',String(r.entregados*110/max));const t=document.createElementNS(ns,'text');t.setAttribute('x',String(i*59+15));t.setAttribute('y','158');t.textContent=String(r.mes).padStart(2,'0');const v=document.createElementNS(ns,'text');v.setAttribute('x',String(i*59+15));v.setAttribute('y',String(133-r.entregados*110/max));v.textContent=r.entregados;svg.append(b,t,v);}$('tendencia').replaceChildren(svg);}

function actividades(){const es=filtrados().filter(e=>e.estado==='En curso'&&!e.cerradoSinConsolidar),cargas=new Map();tabla($('actividades-actuales'),['Cliente / tarea','Responsable / apoyos','Inventarios','Estado'],es.map(e=>[e.cliente+' · '+e.titulo,e.equipo.filter(q=>q.estado==='ACTIVO').map(q=>q.nombre).join(' · ')||e.responsable_nombre||'Sin asignar',(()=>{const d=nodo('div');for(const i of e.inventarios)d.append(enlace(i.codigo_operativo+' · '+i.estado,'/ims?inventario='+i.inventario_id),nodo('br'));return d;})(),e.estado]));for(const e of filtrados().filter(e=>e.estado!=='Entregado'&&!e.cerradoSinConsolidar))for(const q of e.equipo.filter(q=>q.estado==='ACTIVO'))cargas.set(q.nombre,(cargas.get(q.nombre)||0)+1);$('carga-operarios').replaceChildren(...[...cargas].sort((a,b)=>b[1]-a[1]).map(([n,c])=>nodo('p',n+' · '+c+' tareas')));if(!cargas.size)$('carga-operarios').append(nodo('p','Sin asignaciones activas.'));}

async function actualizar(){const seq=++seqDashboard,sedeActual=$('sede').value,r=await api('/api/centro/dashboard'+(sedeActual?'?sede='+encodeURIComponent(sedeActual):''));if(seq!==seqDashboard||$('sede').value!==sedeActual)return;datos=r;$('consulta').textContent='Última consulta: '+new Date(datos.actualizadoEn).toLocaleString('es-EC',{timeZone:'America/Guayaquil'})+' · Ecuador';$('origen').textContent='Panel y cronogramas del corte elegido. Inventarios operativos en MySQL.';tarjetas();calendario();cronograma();archivos();tendencia();actividades();monitor();}
function nuevoEvento(e){editar=e||null;$('evento-titulo-form').textContent=e?'Editar evento':'Nuevo evento';$('evento-sede').value=e?.sede||$('sede').value||ctx.perfil.sedes[0];$('evento-cliente').value=e?.cliente||'';$('evento-titulo').value=e?.titulo||'';$('evento-categoria').value=e?.categoria||'Inventario Cíclico';$('evento-frecuencia').value=e?.frecuencia||'MENSUAL';$('evento-inicio').value=e?.fecha_inicio||hoy();$('evento-duracion').value=e?.duracion||1;$('evento-responsable').value=e?.responsable_id||estado.sesion.usuario.actorId;$('evento-prioridad').value=e?.prioridad||'Media';$('evento-observacion').value=e?.observacion||'';for(const op of $('evento-apoyos').options)op.selected=!!e?.equipo.some(x=>x.actor_id===op.value&&x.papel==='APOYO'&&x.estado==='ACTIVO');$('dialog-evento').showModal();}
async function accion(e,accion,extras={}){await mutar('/api/centro/accion',{eventoId:e.id,version:e.version,accion,...extras});aviso('Evento actualizado.');await actualizar();}
function detalle(titulo,contenido){$('detalle-titulo').textContent=titulo;$('detalle-contenido').replaceChildren(contenido);if(!$('dialog-detalle').open)$('dialog-detalle').showModal();}
function puedeGestionarEvento(e){return ['ADMIN','COORDINADOR'].includes(ctx.perfil.rol)||e.responsable_id===estado.sesion.usuario.actorId||!e.responsable_id&&ctx.perfil.permisos.crear;}
const agendaAncla=document.createComment('agenda en el panel');$('agenda-panel').before(agendaAncla);function ampliarAgenda(){$('agenda-ampliada').append($('agenda-panel'));if(!$('dialog-agenda').open)$('dialog-agenda').showModal();}
$('agenda-ampliar').onclick=ampliarAgenda;$('agenda-cerrar').onclick=()=>$('dialog-agenda').close();$('dialog-agenda').addEventListener('close',()=>agendaAncla.after($('agenda-panel')));for(const id of ['agenda-buscar','agenda-estado'])$(id).addEventListener(id==='agenda-buscar'?'input':'change',calendario);
function detalleEvento(e){const d=nodo('div');for(const t of [e.cliente+' · '+e.titulo,e.sede+' · '+(e.cerradoSinConsolidar?'Cerrado sin consolidar':e.estado),fmt(e.fecha_inicio)+' – '+fmt(fin(e)),'Responsable: '+(e.responsable_nombre||'Sin asignar'),e.observacion])d.append(nodo('p',t));for(const q of e.equipo)d.append(nodo('p',q.nombre+' · '+q.papel+' · '+q.estado));for(const i of e.inventarios){const p=nodo('p');p.append(enlace(i.codigo_operativo+' · '+i.estado,'/ims?inventario='+i.inventario_id),document.createTextNode(' · '),enlace('Excel','/api/centro/inventarios/'+i.inventario_id+'/excel'),document.createTextNode(' · '),enlace('CSV','/api/centro/inventarios/'+i.inventario_id+'/csv'));d.append(p);}if(ctx.perfil.permisos.recordatorios){d.append(boton('Enviar recordatorio',()=>recordatorio(e)),boton('Sincronizar con Google Calendar',()=>encolar('CALENDARIO',{eventoId:e.id})));}if(e.archivo_drive)d.append(enlace('Abrir referencia original de Google','https://docs.google.com/spreadsheets/d/'+encodeURIComponent(e.archivo_drive),'boton'));const a=nodo('div',undefined,'barra');if(ctx.perfil.permisos.crear&&puedeGestionarEvento(e)&&e.estado!=='Entregado'){if(!e.inventarios.length)a.append(enlace('Crear inventario para esta tarea','/crear?evento='+e.id,'boton principal'));a.append(boton('Vincular inventario',()=>vincularExistente(e)));}if(ctx.perfil.permisos.crear&&puedeGestionarEvento(e)&&e.estado!=='Entregado')a.append(boton('Editar tarea y colaboradores',()=>{$('dialog-detalle').close();nuevoEvento(e);}));if(e.estado!=='Entregado')a.append(boton('Unirme como apoyo',async()=>{await accion(e,'apoyar');$('dialog-detalle').close();}));if(ctx.perfil.rol==='ADMIN'||e.responsable_id===estado.sesion.usuario.actorId)a.append(boton('Eliminar evento',async()=>{if(!confirm('Eliminar únicamente este evento del cronograma. Se conservan su auditoría y el inventario.'))return;await accion(e,'eliminar');$('dialog-detalle').close();}));d.append(a);detalle('Detalle de la tarea',d);}
function finalizar(e){const d=nodo('form'),label=nodo('label','Fecha de entrega'),f=nodo('input');f.type='date';f.required=true;f.value=hoy();label.append(f);const b=nodo('button','Registrar entrega','principal');d.append(nodo('p','Confirma la entrega después de finalizar los inventarios vinculados.'),label,b);d.onsubmit=async ev=>{ev.preventDefault();try{await accion(e,'finalizar',{fechaFin:f.value});$('dialog-detalle').close();}catch(err){fallo(err);}};detalle('Finalizar '+e.cliente,d);}
async function usuarios(){const r=await api('/api/centro/usuarios');ctx.personas=r.usuarios;for(const id of ['evento-responsable','evento-apoyos']){const e=$(id),seleccion=new Set([...e.selectedOptions].map(x=>x.value));opciones(e,r.usuarios.filter(u=>u.activo).map(u=>({id:u.actor_id,nombre:u.nombre})),id==='evento-responsable'?'Sin asignar':undefined);for(const o of e.options)o.selected=seleccion.has(o.value);}$('usuarios-resumen').textContent=r.usuarios.length+' cuentas · '+r.usuarios.filter(u=>u.activo).length+' activas · una cuenta por persona para Centro y conteo';opciones($('nuevo-rol'),r.roles);tabla($('usuarios-lista'),['Nombre','Correo','Perfil de acceso','Sedes','Estado','Acción'],r.usuarios.filter(u=>{const q=$('usuarios-buscar').value.toLocaleLowerCase('es'),f=$('usuarios-estado').value;return (!q||(u.nombre+' '+u.correo).toLocaleLowerCase('es').includes(q))&&(!f||u.activo===(f==='activo'));}).map(u=>{const a=nodo('div',undefined,'acciones');if(ctx.perfil.rol==='ADMIN'&&u.actor_id!==estado.sesion.usuario.actorId)a.append(boton('Editar perfil',()=>editarUsuario(u)),boton('Restablecer clave',()=>claveUsuario(u)),boton(u.activo?'Desactivar':'Activar',async()=>{await mutar('/api/centro/usuario-estado',{actorId:u.actor_id,activo:!u.activo});await usuarios();}));return[u.nombre,u.correo,u.rol+' · '+(u.rol_wms==='ADMIN'?'gestiona conteos':u.rol_wms==='OPERADOR'?'captura':'consulta'),u.sedes.join(', '),u.activo?'Activo':u.cambiar_clave?'Pendiente de clave / activación':'Inactivo',a];}));}
function editarUsuario(u){const d=nodo('form'),l=nodo('label','Perfil del Centro de Mando'),rol=nodo('select'),w=nodo('label','Permiso de conteo'),wms=nodo('select'),ls=nodo('label','Sedes autorizadas'),sedes=nodo('select');opciones(rol,['ADMIN','COORDINADOR','LIDER','OPERARIO','AUDITOR']);rol.value=u.rol;opciones(wms,['ADMIN','OPERADOR','AUDITOR']);wms.value=u.rol_wms;opciones(sedes,ctx.perfil.sedes);sedes.multiple=true;sedes.size=2;for(const op of sedes.options)op.selected=u.sedes.includes(op.value);l.append(rol);w.append(wms);ls.append(sedes);d.append(l,w,ls,nodo('button','Guardar permisos','principal'));d.onsubmit=async e=>{e.preventDefault();try{await mutar('/api/centro/usuario-rol',{actorId:u.actor_id,rol:rol.value,rolWms:wms.value,sedes:[...sedes.selectedOptions].map(x=>x.value)});$('dialog-detalle').close();await usuarios();aviso('Permisos actualizados. Las sesiones anteriores de la cuenta se cerraron.');}catch(err){fallo(err);}};detalle(u.nombre+' · Perfil',d);}
function claveUsuario(u){const d=nodo('form'),l=nodo('label','Nueva contraseña temporal · mínimo 12 caracteres'),f=nodo('input'),operacionId=crypto.randomUUID();f.type='password';f.minLength=12;f.required=true;f.autocomplete='new-password';l.append(f);d.append(l,nodo('p','La persona deberá cambiarla al entrar. No se envía por correo ni se conserva en el navegador.'),nodo('button','Restablecer contraseña','principal'));d.onsubmit=async e=>{e.preventDefault();try{await api('/api/centro/usuario-clave',{operacionId,actorId:u.actor_id,contrasena:f.value});f.value='';$('dialog-detalle').close();aviso('Contraseña restablecida. Se cerraron las sesiones anteriores de la cuenta.');}catch(err){fallo(err);}};detalle('Restablecer contraseña de '+u.nombre,d);}

async function analitica(){const r=await api('/api/centro/analitica');tabla($('analitica-lista'),['Nombre','Responsable','Apoyos','Exclusiones','Asignados','Entregados','En curso','Pendientes'],r.usuarios.map(u=>[u.nombre,u.responsabilidades,u.apoyos,u.exclusiones,u.asignados,u.entregados,u.enCurso,u.pendientes]));}
async function consolidar(publicar){if(publicar&&!confirm('Publicar los KPI de los inventarios Entregados después de su verificación WMS.'))return;aviso('Verificando inventarios y cantidades exactas…');const j=await mutar('/api/centro/trabajos',{tipo:publicar?'PUBLICACION':'AUDITORIA'});const r=await esperarTrabajo(j.trabajoId);const d=nodo('div');d.append(nodo('p',r.entregadosVerificados+' entregados verificados · '+r.publicados+' publicados · '+r.incidencias.length+' incidencias.'));if(r.incidencias.length)tabla(d,['Inventario','Motivo'],r.incidencias.map(x=>[x.inventarioId,x.motivo]));detalle('Resultado de consolidación',d);await actualizar();}
const mesesCortos=['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'];
let vistaCodigo=null,seqCodigos=0;
async function consultarCodigos(){if(!$('codigo-cliente').value.trim()){$('codigos-resumen').textContent='Selecciona el cliente para consultar su programación.';$('codigos-lista').replaceChildren();$('codigos-meses').replaceChildren();return;}const seq=++seqCodigos,q=new URLSearchParams({sede:$('codigo-sede').value,cliente:$('codigo-cliente').value,buscar:$('codigo-buscar').value,mes:$('codigo-mes').value});try{const r=await api('/api/centro/codigos?'+q);if(seq!==seqCodigos)return;$('codigos-resumen').textContent=$('codigo-cliente').value+' · '+r.totalCodigos+' códigos · '+r.totalCoincidencias+' coinciden con el filtro'+(r.totalCoincidencias>r.datos.length?' · mostrando los primeros '+r.datos.length:'');$('codigos-meses').replaceChildren(...r.totalesPorMes.map((n,i)=>{const b=boton(mesesCortos[i]+' · '+n,()=>{$('codigo-mes').value=String(i+1);invalidarCodigo();return consultarCodigos();},'codigo-mes-tarjeta');b.classList.toggle('activo',Number($('codigo-mes').value)===i+1);b.title='Consultar '+mesesCortos[i];return b;}));tabla($('codigos-lista'),['SKU','ABC',...mesesCortos],r.datos.map(x=>[x.sku,x.abc,...mesesCortos.map((m,i)=>nodo('span',x.meses.includes(i+1)?'●':'—',x.meses.includes(i+1)?'codigo-programado':'codigo-sin-programar'))]));}catch(e){$('codigos-resumen').textContent=e.message;}}
