function abrirMigracionCentro(){planCentro=null;operacionCentro=null;$('centro-migracion-aplicar').disabled=true;$('centro-migracion-resumen').textContent='';$('centro-migracion-muestra').replaceChildren();$('centro-migracion-resultado').textContent='';$('centro-migracion-anio').value=hoy().slice(0,4);opciones($('centro-migracion-sedes'),ctx.perfil.sedes);for(const o of $('centro-migracion-sedes').options)o.selected=true;$('dialog-migracion-centro').showModal();}
$('revisar-centro').onclick=abrirMigracionCentro;$('usuarios-migrar').onclick=abrirMigracionCentro;
$('centro-migracion-leer').onclick=async()=>{const b=$('centro-migracion-leer');b.disabled=true;planCentro=null;operacionCentro=null;$('centro-migracion-aplicar').disabled=true;$('centro-migracion-resumen').textContent='Leyendo el cronograma y los perfiles actuales de Google…';try{const j=await api('/api/centro/trabajos',{operacionId:crypto.randomUUID(),tipo:'CENTRO_REVISION',anio:$('centro-migracion-anio').value}),r=await esperarTrabajo(j.trabajoId);planCentro=r.planId;$('centro-migracion-resumen').textContent=r.tareas.length+' tareas · '+r.usuarios.length+' cuentas de origen · '+r.incidencias.length+' incidencias. No se han modificado datos.';const t=nodo('div');tabla(t,['Cliente','Tarea','Inicio','Estado','Acción','Motivo'],r.tareas.map(x=>[x.cliente,x.titulo,x.fechaInicio,x.estado,x.accion,x.motivo||'']));const u=nodo('div');u.append(nodo('h3','Cuentas existentes y nuevas'));const ut=nodo('div');u.append(ut);tabla(ut,['Nombre','Correo','Rol','Acción'],r.usuarios.map(x=>[x.nombre,x.correo,x.rol,x.accion]));$('centro-migracion-muestra').replaceChildren(t,u);$('centro-migracion-aplicar').disabled=false;}catch(e){$('centro-migracion-resumen').textContent=e.message;}finally{b.disabled=false;}};
$('centro-migracion-aplicar').onclick=async()=>{if(!planCentro)return;const b=$('centro-migracion-aplicar'),s={planId:planCentro,cronograma:$('centro-migracion-cronograma').checked,usuarios:$('centro-migracion-usuarios').checked,sedesUsuarios:[...$('centro-migracion-sedes').selectedOptions].map(x=>x.value)};b.disabled=true;try{if(!operacionCentro||JSON.stringify(operacionCentro.s)!==JSON.stringify(s))operacionCentro={id:crypto.randomUUID(),s};const j=await api('/api/centro/trabajos',{operacionId:operacionCentro.id,tipo:'CENTRO_APLICAR',...s}),r=await esperarTrabajo(j.trabajoId);$('centro-migracion-resultado').textContent=r.eventosNuevos+' tareas nuevas · '+r.eventosActualizados+' actualizadas · '+r.usuariosNuevos+' cuentas nuevas pendientes de clave · '+r.usuariosExistentesConservados+' cuentas existentes conservadas · '+r.incidencias.length+' incidencias. Revisa Usuarios para restablecer las claves pendientes y activar las cuentas.';if(r.incidencias.length){const t=nodo('div');tabla(t,['Fila / tarea','Motivo'],r.incidencias.map(x=>[x.fila||x.eventoId||'',x.codigo]));$('centro-migracion-resultado').append(t);}await actualizar();await usuarios();}catch(e){$('centro-migracion-resultado').textContent=e.message;}finally{b.disabled=false;}};

async function copiarIncorporacionGoogle(){try{const r=await api('/api/centro/sincronizacion'),texto=JSON.stringify(r.incorporacionGoogle,null,2);await navigator.clipboard.writeText(texto);aviso('Resumen de revisión e incorporación copiado. No incluye claves ni filas de inventario.');}catch(e){fallo(e);}}
$('fuentes-copiar-incorporacion').onclick=copiarIncorporacionGoogle;

// Consulta administrativa: sin aplicar planes, cambiar estados ni enviar avisos.
$('fuentes-cierre').onclick=async()=>{
 const b=$('fuentes-cierre');b.disabled=true;
 try{
  const r=await api('/api/centro/cierre'),d=nodo('div'),cuentas=r.cuentasOperacion;
  d.append(nodo('p',r.pendientes.length?r.pendientes.length+' puntos requieren atención antes del cierre.':'Los datos y accesos consultados no muestran pendientes. Falta confirmar la validación en campo.'),
   nodo('p','Periodo: '+r.periodo.desde+' a '+r.periodo.hasta+' · '+cuentas.lideresActivos+' líderes activos · '+cuentas.operariosActivos+' operarios activos · '+cuentas.conAccesoDeCaptura+' personas con acceso a captura.'),
   nodo('p','Capturas locales del periodo: C1 '+r.capturasLocales30Dias.c1+' · C2 '+r.capturasLocales30Dias.c2+' · C3 '+r.capturasLocales30Dias.c3+'. Las incorporaciones de Google se consultan por separado.'));
  const aplicada=r.google.aplicacion;d.append(nodo('p',aplicada?'Último intento de incorporación Google: '+aplicada.estado+' · '+aplicada.inventariosNuevos+' inventarios nuevos · '+aplicada.capturasAgregadas+' capturas agregadas.':'No hay una incorporación de Google registrada.'));
  const pendientes=nodo('div');tabla(pendientes,['Pendiente','Acción'],r.pendientes.map(x=>[x.cantidad?x.cantidad+(x.cantidad===1?' caso':' casos'):'Por confirmar',x.accion]));d.append(pendientes,nodo('h3','Inventarios recientes y equipo habilitado'));
  const recientes=nodo('div');tabla(recientes,['Sede','Inventario','Estado','Asignación'],r.recientes.map(i=>[i.sede,i.codigo,i.borrador?'Stock pendiente':({EN_PROCESO:'En conteo',EN_VALIDACION:'En validación'}[i.estado]||i.estado),i.clientesSinLider||i.clientesSinEquipoHabilitado?i.clientesSinLider+(i.clientesSinLider===1?' cliente sin líder':' clientes sin líder')+' · '+i.clientesSinEquipoHabilitado+' sin equipo habilitado':'Equipo habilitado para todos los clientes']));d.append(recientes);
  if(r.google.revision?.fuentesPendientesDeIniciar)d.append(nodo('p',r.google.revision.fuentesPendientesDeIniciar+' fuentes pendientes de iniciar se conservan separadas.'));
  if(r.google.conflictosAnteriores)d.append(nodo('p',r.google.conflictosAnteriores+' conflictos de inventarios anteriores se conservan para revisión separada.'));
  if(r.google.periodoReciente.comprobacion==='INCOMPLETA_POR_FUENTES_NO_CONFIRMADAS')d.append(nodo('p','La lectura es parcial: que no aparezcan novedades no confirma que todos los archivos estén incorporados.'));
  if(r.google.revision?.detalleIncidencias?.length){d.append(nodo('h3','Fuentes que requieren atención'));const t=nodo('div');tabla(t,['Fila del panel','Estado HTTP','Acción'],r.google.revision.detalleIncidencias.map(i=>[i.filaPanel||'Sin referencia',i.http||i.codigo,i.accion]));d.append(t);}
  d.append(nodo('p',r.validacionEnCampo));const copiar=nodo('button','Copiar informe para soporte');copiar.type='button';copiar.onclick=async()=>{try{await navigator.clipboard.writeText(JSON.stringify(r,null,2));aviso('Informe de cierre copiado. No incluye contraseñas ni datos de conexión.');}catch(e){fallo(e);}};d.append(copiar);detalle('Cierre operativo',d);
 }catch(e){fallo(e);}finally{b.disabled=false;}
};

function abrirSeccionConexiones(id){
 document.querySelector('.conexiones-cuerpo').scrollTop=0;
 for(const b of document.querySelectorAll('[data-conexion]')){const activo=b.dataset.conexion===id;b.setAttribute('aria-selected',String(activo));b.tabIndex=activo?0:-1;document.getElementById(b.getAttribute('aria-controls')).hidden=!activo;}
}
for(const b of document.querySelectorAll('[data-conexion]')){b.onclick=()=>abrirSeccionConexiones(b.dataset.conexion);b.onkeydown=e=>{const tabs=[...document.querySelectorAll('[data-conexion]')],i=tabs.indexOf(b);let siguiente;if(e.key==='ArrowRight')siguiente=tabs[(i+1)%tabs.length];if(e.key==='ArrowLeft')siguiente=tabs[(i+tabs.length-1)%tabs.length];if(e.key==='Home')siguiente=tabs[0];if(e.key==='End')siguiente=tabs.at(-1);if(siguiente){e.preventDefault();siguiente.click();siguiente.focus();}};}

document.addEventListener('ims:conexiones',e=>{if(ctx?.perfil.permisos.administrar)abrirConexiones(e.detail?.seccion==='cuenta'?'cuenta':'inventarios').catch(fallo);});

async function recuperarRevisionGoogle(){const epoca=epocaGoogle;try{const r=await api('/api/centro/revision-google');if(epoca!==epocaGoogle||leyendoGoogle||!r.lectura)return;planGoogle=r.lectura;revisionGoogle.cargar(r.lectura,r);if(!$('conexion-panel-inventarios').hidden)document.querySelector('.conexiones-cuerpo').scrollTop=0;$('google-delta-recientes').disabled=!revisionGoogle.hayRecientes();}catch(e){if(epoca===epocaGoogle&&!leyendoGoogle)$('google-delta-resumen').textContent='La última lectura no está disponible para esta cuenta. Puedes preparar una consulta nueva.';}}

function estadoFuente(j,google){if(!j)return 'Sin ejecución registrada';if(j.estado!=='COMPLETO')return ({PENDIENTE:'En cola',EJECUTANDO:'En curso',ERROR:'Requiere revisión',CANCELADO:'Cancelado'})[j.estado]||j.estado;if(j.tipo==='GOOGLE_DELTA'){const r=google?.revision;return r?.otrasIncidencias?'Lectura parcial · '+r.otrasIncidencias+' fuentes por verificar':'Lectura completa · '+(r?.archivosConfirmados??'—')+' archivos · '+(google?.periodoReciente.gruposConConflictos||0)+' inventarios recientes por revisar';}if(j.tipo==='GOOGLE_APLICAR')return j.incidencias?'Incorporación con '+j.incidencias+' incidencias pendientes':'Incorporación confirmada · '+(j.capturasAgregadas??0)+' capturas';return j.incidencias?'Finalizado con '+j.incidencias+' avisos':'Completado';}
